DEP_project_task_schedule.invariants_dsl:
spec Task {
    field duration_days: Integer {
        value >= 1;
        value <= 21;
    }
    field task_type: String {
        value IN ["design", "development", "testing", "review", "deployment"];
    }
}

spec ProjectSchedule {
    field project_deadline_day: Integer {
        value >= 30;
        value <= 180;
    }
    field task1_start_day: Integer {
        value >= 0;
        value <= 5;
    }
    field task1: Task {}
    field task2_start_day: Integer {}
    field task2: Task {}
    field task3_start_day: Integer {}
    field task3: Task {}
    field task4_start_day: Integer {}
    field task4: Task {}
    field task5_start_day: Integer {}
    field task5: Task {}
    invariant sequencing {
        this.task2_start_day >= this.task1_start_day + this.task1.duration_days;
        this.task3_start_day >= this.task2_start_day + this.task2.duration_days;
        this.task4_start_day >= this.task3_start_day + this.task3.duration_days;
        this.task5_start_day >= this.task4_start_day + this.task4.duration_days;
    }
    invariant deadline {
        this.task5_start_day + this.task5.duration_days <= this.project_deadline_day;
    }
}

DEP_flight_multi_leg_itinerary.invariants_dsl:
spec FlightLeg {
    field departure_offset_hours: Integer {
        value >= 0;
        value <= 96;
    }
    field flight_duration_hours: Integer {
        value >= 1;
        value <= 14;
    }
    field destination_code: String {
        value IN ["JFK", "LHR", "NRT", "SIN", "DXB", "SYD"];
    }
}

spec Itinerary {
    field min_layover_hours: Integer {
        value >= 1;
        value <= 6;
    }
    field leg1: FlightLeg {}
    field leg2: FlightLeg {}
    field leg3: FlightLeg {}
    invariant connections {
        this.leg2.departure_offset_hours >= this.leg1.departure_offset_hours + this.leg1.flight_duration_hours + this.min_layover_hours;
        this.leg3.departure_offset_hours >= this.leg2.departure_offset_hours + this.leg2.flight_duration_hours + this.min_layover_hours;
    }
}
